def transform(grid):
    divider = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0)
    upper, lower = grid[:divider], grid[divider + 1:]
    colors = {v for row in grid for v in row if v not in (0, grid[divider][0])}
    delta = {c: sum(v == c for row in lower for v in row) - sum(v == c for row in upper for v in row) for c in colors}
    color = max(colors, key=lambda c: delta[c])
    return [[color, color], [color, color]]

if __name__ == '__main__':
    demos = [
        ([[0,0,2,0,0,0,4,0,0],[0,0,0,0,0,0,4,0,0],[0]*9,[0]*9,[5]*9,[0,0,2,0,0,0,4,0,0],[0,0,2,0,0,0,4,0,0],[0,0,0,0,0,0,4,0,0],[0,0,0,0,0,0,4,0,0]], 4),
